def analytic_gold(scene):
    good=[]
    for k,s in enumerate(scene['strips']):
        v=s['occupied']
        if any(not a and not b for a,b in zip(v,v[1:])):
            good.append(k)
    if len(good)!=1:
        raise ValueError('Expected exactly one qualifying strip')
    return 'left' if good[0]==0 else 'right'
